#include "legacy.hpp"
#include "plan_generator.hpp"
#include <iostream>
int main(int argc,char **argv){using namespace puck::execute;Options o;for(int i=2;i<argc;++i)o.args.emplace_back(argv[i]);configure(o);std::string mode=argv[1];Steps s;auto start=nominal_pose();if(mode=="replan") { if(argc!=6) return 2;auto p=replan(std::stod(argv[4]),std::stod(argv[5]),argv[3],argv[2]);return p?0:1; } if(mode=="math") { Json j; j["nominal"]=nominal_pose(); j["via"]=via_pose(); j["carry"]=carry_via_path(); j["below"]=below(load_pose(),.005); j["above"]=above(load_pose(),.005); auto q=stand_grasp(5); auto app=approach_at(112.5,q[0],q[4]); j["jaw"]=jaw_fix(q); j["shift"]=shift_ahead(q,2.0); auto line=line_up(q,3.,1);j["line"]=line ? Json(*line) : Json(nullptr); auto [approach,path,note]=descent(q,app);j["descent"]=Json::array({approach,path,note}); j["wait"]=Json::array({wait_at(52.5,q[0]),wait_at(97.,q[0]),wait_at(157.,q[0])});std::cout<<j.dump();return 0;} if(mode=="stand")s=stand_steps({},start);else if(mode=="standcal")s=standcal_steps({},start);else if(mode=="find")s=find_steps({},start);else if(mode=="lie")s=lie_steps({},start);else if(mode=="dice_line") { auto [path,q]=dice_line(dice_lm("centre").first,argc>2 ? argv[2] : "near"); std::cout<<Json({path,q}).dump(); return 0; } if(mode=="plan")s=steps_from_plan({},start);else if(mode=="lying")s=lying_steps_from_plan({},start);else if(mode=="dice")s=dice_steps({},start);else if(mode=="unload")s=unload_steps({},start);else if(mode=="bigbro")s=bigbro_steps({},start);else if(mode=="gripzero")s=gripzero_steps({},start);else if(mode=="gripcal")s=gripcal_steps({},start);Json j=Json::array();for(const auto &x:s)j.push_back({x.name,x.kind,x.arg});std::cout<<j.dump();}
